package com.himeros.match;import com.himeros.shared.CurrentUser;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/matches")public class MatchController{private final MatchService service;private final CurrentUser current;public MatchController(MatchService service,CurrentUser current){this.service=service;this.current=current;}@GetMapping List<MatchService.MatchView> list(){return service.list(current.id());}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void unmatch(@PathVariable UUID id){service.unmatch(current.id(),id);}}
